import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        Node head = null, tail = null;
        for (int i = 0; i < n; i++) {
            Node node = new Node(Integer.parseInt(st.nextToken()));
            if (head == null) head = tail = node; else { tail.next = node; tail = node; }
        }
        int k = Integer.parseInt(br.readLine().trim());
        Node dummy = new Node(0);
        dummy.next = head;
        Node fast = dummy, slow = dummy;
        for (int i = 0; i < k; i++) fast = fast.next;
        while (fast.next != null) { fast = fast.next; slow = slow.next; }
        slow.next = slow.next.next;
        head = dummy.next;
        if (head == null) { System.out.println("EMPTY"); return; }
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(c.val).append(' ');
        System.out.println(sb.toString().trim());
    }
}

